// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlightsList,
    updateHighlight,
    deleteLink,
    deleteCollection
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const take = "1";

    const collectionsPostResponse = await createCollection(client, "Testbot Highlights Library", "#0ea5e9");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Testbot Highlights Library");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'collection color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection id').toBeGreaterThan(0);

    const linksPostResponse = await createLink(
        client,
        "Testbot Highlights Source",
        "https://example.com/testbot-highlights",
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Testbot Highlights Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/testbot-highlights");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'link collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'link id').toBeGreaterThan(0);

    const highlightsPostResponse = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "yellow",
        "Testbot alpha passage about migration",
        "remember this quotation",
        0,
        37
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'alpha colour').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'alpha text').toBe("Testbot alpha passage about migration");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'alpha note').toBe("remember this quotation");
    expect(getResponseValue(highlightsPostResponse, "response.startOffset"), 'alpha startOffset').toBe(0);
    expect(getResponseValue(highlightsPostResponse, "response.endOffset"), 'alpha endOffset').toBe(37);
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'alpha link').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'alpha id').toBeGreaterThan(0);
    expect(getResponseValue(highlightsPostResponse, "response.createdAt"), 'alpha createdAt is a timestamp').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const highlightsPost1Response = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "green",
        "Testbot beta passage about indexing",
        "second note",
        40,
        75
    );
    expect(highlightsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPost1Response, "response.color"), 'beta colour').toBe("green");
    expect(getResponseValue(highlightsPost1Response, "response.text"), 'beta text').toBe("Testbot beta passage about indexing");
    expect(getResponseValue(highlightsPost1Response, "response.comment"), 'beta note').toBe("second note");
    expect(getResponseValue(highlightsPost1Response, "response.linkId"), 'beta link').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPost1Response, "response.id"), 'beta id').toBeGreaterThan(0);

    const highlightsGetResponse = await getHighlightsList(client, {});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    // Newest id first, each row carrying its source link.
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'newest row is the beta highlight').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1.id"), 'second row is the alpha highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id") > getResponseValue(highlightsGetResponse, "response.highlights.1.id"), 'rows are ordered newest id first').toBe(true);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.id"), 'source link id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.name"), 'source link name').toBe("Testbot Highlights Source");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.url"), 'source link url').toBe("https://example.com/testbot-highlights");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.2"), 'no third row for this run').toBeNull();

    const highlightsGet1Response = await getHighlightsList(client, {"q": ["beta"]});
    expect(highlightsGet1Response.statusCode, 'status code').toBe(200);
    // "beta" appears only in the beta highlight's text.
    expect(getResponseValue(highlightsGet1Response, "response.highlights").length, 'one text match').toBe(1);
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.id"), 'text match is the beta highlight').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.text"), 'text match text').toBe("Testbot beta passage about indexing");
    expect(getResponseValue(highlightsGet1Response, "response.highlights.1"), 'no second text match').toBeNull();

    const highlightsGet2Response = await getHighlightsList(client, {"q": ["quotation"]});
    expect(highlightsGet2Response.statusCode, 'status code').toBe(200);
    // "quotation" appears only in the alpha highlight's NOTE, never in any text.
    expect(getResponseValue(highlightsGet2Response, "response.highlights").length, 'one note match').toBe(1);
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0.id"), 'note match is the alpha highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0.comment"), 'note match comment').toBe("remember this quotation");
    expect(getResponseValue(highlightsGet2Response, "response.highlights.1"), 'no second note match').toBeNull();

    const highlightsGet3Response = await getHighlightsList(client, {"q": ["zzzznomatchzzzz"]});
    expect(highlightsGet3Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet3Response, "response.highlights").length, 'no matches').toBe(0);
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0"), 'no first match').toBeNull();
    expect(getResponseValue(highlightsGet3Response, "response.nextCursor"), 'no next page').toBeNull();

    const highlightsGet4Response = await getHighlightsList(client, {"color": ["green"]});
    expect(highlightsGet4Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet4Response, "response.highlights").length, 'one green row').toBe(1);
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0.id"), 'green row is the beta highlight').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0.color"), 'green row colour').toBe("green");
    expect(getResponseValue(highlightsGet4Response, "response.highlights.1"), 'no second green row').toBeNull();

    const highlightsGet5Response = await getHighlightsList(client, {"take": [take]});
    expect(highlightsGet5Response.statusCode, 'status code').toBe(200);
    // take=1 returns one row and a cursor pointing at it.
    expect(getResponseValue(highlightsGet5Response, "response.highlights").length, 'first page holds one row').toBe(1);
    expect(getResponseValue(highlightsGet5Response, "response.highlights.0.id"), 'first page row').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet5Response, "response.nextCursor"), 'nextCursor is the last id of the page').toBe(getResponseValue(highlightsGet5Response, "response.highlights.0.id"));

    const highlightsGet6Response = await getHighlightsList(client, {
        "cursor": [getResponseValue(highlightsGet5Response, "response.nextCursor")],
        "take": [take]
    });
    expect(highlightsGet6Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet6Response, "response.highlights").length, 'second page holds one row').toBe(1);
    expect(getResponseValue(highlightsGet6Response, "response.highlights.0.id"), 'second page row is the alpha highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet6Response, "response.highlights.0.id") < getResponseValue(highlightsGet5Response, "response.highlights.0.id"), 'the cursor moved forward').toBe(true);

    const highlightsHighlightsPatchRequestBody: string = `{
        "color": "blue",
        "comment": "Testbot edited note"
    }`;
    const highlightsHighlightsPatchResponse = await updateHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        highlightsHighlightsPatchRequestBody
    );
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.id"), 'patched the alpha highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.color"), 'patched colour').toBe("blue");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.comment"), 'patched note').toBe("Testbot edited note");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.text"), 'patch leaves the highlighted text alone').toBe("Testbot alpha passage about migration");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.link.id"), 'patched row carries its source link').toBe(getResponseValue(linksPostResponse, "response.id"));

    const highlightsGet7Response = await getHighlightsList(client, {"color": ["blue"]});
    expect(highlightsGet7Response.statusCode, 'status code').toBe(200);
    // The edit is persisted, so the blue filter now returns it.
    expect(getResponseValue(highlightsGet7Response, "response.highlights").length, 'one blue row').toBe(1);
    expect(getResponseValue(highlightsGet7Response, "response.highlights.0.id"), 'blue row is the edited highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet7Response, "response.highlights.0.comment"), 'blue row carries the edited note').toBe("Testbot edited note");
    expect(getResponseValue(highlightsGet7Response, "response.highlights.1"), 'no second blue row').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted the link this test created').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted the collection this test created').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
